import {TIP_DEFAULTS,imageTip,validateTip,visitTip,validateTipLibrary,emptyLibrary} from './custom-tips.js';
import {decodeImageFile} from './image-import.js';
const KEY='unruly-image-tips-v1';
export function initTipUI({$,settings,renderer,blocked,status,onSelect}){
 let library=emptyLibrary(),selected=null,draft=null,decoded=null,loading=false;
 try{const raw=localStorage.getItem(KEY);if(raw)library=validateTipLibrary(JSON.parse(raw));}catch{status('Saved brush library could not be read; import a brush backup to recover',true);}
 const controls=Object.keys(TIP_DEFAULTS),editor=$('tip-editor');
 function persist(candidate){validateTipLibrary(candidate);localStorage.setItem(KEY,JSON.stringify(candidate));library=candidate;render();}
 function action(fn){if(blocked())return;try{fn();}catch(e){status(e.message,true);}}
 function choose(b){if(blocked())return;selected=b.id;settings.brush='ink';settings.preset='ink-brush';settings.tip=structuredClone(b.tip);delete settings.recipe;$('paint-mode').value='vector';$('paint-mode').dispatchEvent(new Event('change'));onSelect();render();status(b.name+' · image tip selected');}
 function render(){const section=$('tip-section').value;$('tip-section').replaceChildren();for(const s of library.sections){const o=new Option(s.name,s.id);$('tip-section').add(o);}$('tip-section').value=library.sections.some(s=>s.id===section)?section:library.sections[0].id;const active=library.brushes.find(b=>b.id===selected);if(active&&settings.tip)$('brush-current').textContent=library.sections.find(s=>s.id===active.section).name+' · '+active.name;const root=$('tip-brushes');root.replaceChildren();for(const b of library.brushes.filter(b=>b.section===$('tip-section').value)){const button=document.createElement('button');button.type='button';button.textContent=b.name;button.setAttribute('aria-pressed',String(selected===b.id&&!!settings.tip));button.onclick=()=>choose(b);const edit=document.createElement('button');edit.textContent='Edit '+b.name;edit.type='button';edit.onclick=()=>action(()=>open(b));root.append(button,edit);}}
 function fields(){for(const k of controls){const el=$('tip-'+k);if(typeof TIP_DEFAULTS[k]==='boolean')el.checked=draft.tip.options[k];else el.value=draft.tip.options[k];}}
 function readFields(){const t=structuredClone(draft.tip);for(const k of controls){const el=$('tip-'+k);t.options[k]=typeof TIP_DEFAULTS[k]==='boolean'?el.checked:typeof TIP_DEFAULTS[k]==='number'?(el.value===''?NaN:Number(el.value)):el.value;}return validateTip(t);}
 function preview(){try{const tip=readFields();const stroke={id:'tip-preview',brush:'ink',preset:'ink-brush',tip,color:settings.color,size:32,opacity:1,dynamics:settings.dynamics,points:[{x:20,y:42,pressure:.3},{x:110,y:20,pressure:1},{x:250,y:42,pressure:.6}]};visitTip(stroke);$('tip-preview').src=renderer.preview(stroke,280,80);$('tip-error').textContent='';draft.tip=tip;}catch(e){$('tip-error').textContent=e.message;}}
 function open(b){draft=structuredClone(b||{id:'tip-'+crypto.randomUUID(),name:decoded?.name?.replace(/\.[^.]+$/,'')||'Image brush',section:$('tip-section').value,tip:imageTip(decoded,$('tip-source').value,$('tip-invert').checked)});$('tip-name').value=draft.name;$('tip-destination').replaceChildren();for(const s of library.sections)$('tip-destination').add(new Option(s.name,s.id));$('tip-destination').value=draft.section;$('tip-source-controls').hidden=!decoded;$('tip-delete').hidden=!b;fields();editor.showModal();preview();$('tip-name').focus();}
 function cancel(){if(loading)return;draft=null;decoded=null;editor.close();}
 $('tip-upload').onclick=()=>action(()=>$('tip-file').click());
 $('tip-file').onchange=async()=>{const f=$('tip-file').files[0];$('tip-file').value='';if(!f||blocked())return;loading=true;try{decoded=await decodeImageFile(f);$('tip-source').value=decoded.data.some((v,i)=>i%4===3&&v<255)?'alpha':'grayscale';$('tip-invert').checked=false;try{imageTip(decoded,$('tip-source').value);}catch{$('tip-source').value='alpha';}loading=false;open(null);}catch(e){decoded=null;status('Tip rejected · '+e.message,true);}finally{loading=false;}};
 for(const k of controls)$('tip-'+k).oninput=preview;
 for(const id of ['tip-source','tip-invert'])$(id).onchange=()=>{try{const options=readFields().options;draft.tip={...imageTip(decoded,$('tip-source').value,$('tip-invert').checked),options};preview();}catch(e){$('tip-error').textContent=e.message;}};
 $('tip-save').onclick=()=>{if(!draft)return;try{const b={...draft,tip:readFields(),name:$('tip-name').value.trim(),section:$('tip-destination').value},next=structuredClone(library),i=next.brushes.findIndex(x=>x.id===b.id);if(i<0)next.brushes.push(b);else next.brushes[i]=b;persist(next);draft=null;decoded=null;editor.close();choose(b);}catch(e){$('tip-error').textContent=e.message;}};
 $('tip-delete').onclick=()=>{if(!draft)return;try{const next=structuredClone(library);next.brushes=next.brushes.filter(b=>b.id!==draft.id);persist(next);cancel();status('Library brush removed · existing artwork retains its tip');}catch(e){$('tip-error').textContent=e.message;}};
 $('tip-cancel').onclick=cancel;editor.addEventListener('cancel',e=>{e.preventDefault();cancel();});
 $('tip-section').onchange=render;
 $('tip-section-create').onclick=()=>action(()=>{const next=structuredClone(library),name=$('tip-section-name').value.trim();next.sections.push({id:crypto.randomUUID(),name});persist(next);$('tip-section').value=next.sections.at(-1).id;render();$('tip-section-name').value='';});
 $('tip-section-rename').onclick=()=>action(()=>{const next=structuredClone(library);next.sections.find(s=>s.id===$('tip-section').value).name=$('tip-section-name').value.trim();persist(next);$('tip-section-name').value='';});
 $('tip-library-export').onclick=()=>action(()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(library)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='unruly-brush-library.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 $('tip-library-import').onclick=()=>action(()=>$('tip-library-file').click());
 $('tip-library-file').onchange=async()=>{const f=$('tip-library-file').files[0];$('tip-library-file').value='';if(!f||blocked())return;loading=true;try{if(f.size>1048576)throw Error('Brush library exceeds 1 MiB');const imported=validateTipLibrary(JSON.parse(await f.text())),next=structuredClone(library),map=new Map();for(const s of imported.sections){let target=next.sections.find(x=>x.name===s.name);if(!target){target={id:crypto.randomUUID(),name:s.name};next.sections.push(target);}map.set(s.id,target.id);}for(const b of imported.brushes)next.brushes.push({...b,id:'tip-'+crypto.randomUUID(),section:map.get(b.section)});persist(next);status('Brush library imported into named sections');}catch(e){status('Brush library rejected · '+e.message,true);}finally{loading=false;}};
 render();return {editing:()=>!!draft||loading,key:()=>selected&&settings.tip?selected:null,clear:()=>{selected=null;delete settings.tip;render();}};
}
